import React, { useEffect, useState } from "react";

function OrdersList() {
  const [orders, setOrders] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    fetch("http://localhost/api/comandes")
      .then((res) => {
        if (!res.ok) throw new Error("Error al obtenir les comandes");
        return res.json();
      })
      .then((data) => {
        setOrders(Array.isArray(data.dades) ? data.dades : []);
        setLoading(false);
      })
      .catch((err) => {
        console.error(err);
        setError(err.message);
        setLoading(false);
      });
  }, []);

  if (loading) return <p>Carregant comandes...</p>;
  if (error) return <p className="text-danger">Error: {error}</p>;
  if (orders.length === 0) return <p>No hi ha comandes disponibles.</p>;

  return (
    <div className="container mt-4">
      <h2>Comandes</h2>

      <table className="table table-striped">
        <thead>
          <tr>
            <th>ID</th>
            <th>Data</th>
            <th>Tipus</th>
            <th>Client</th>
            <th>Proveïdor</th>
          </tr>
        </thead>

        <tbody>
          {orders.map((order) => (
            <tr key={order.id}>
              <td>{order.id}</td>
              <td>{order.data}</td>
              <td>{order.tipus}</td>

              <td>
                {order.client ? order.client.nom : "—"}
              </td>

              <td>
                {order.proveidor ? order.proveidor.nom : "—"}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

export default OrdersList;
